class Solution:
    def maximumSum(self, arr):
        n = len(arr)
        f = arr[:]
        g = arr[:]
        for i in range(1, n):
            f[i] = max(arr[i], f[i-1] + arr[i])
        for i in range(n-2, -1, -1):
            g[i] = max(arr[i], g[i+1] + arr[i])
        ans = max(f)
        for i in range(1, n-1):
            ans = max(ans, f[i-1] + g[i+1])
        return ans

