public:
    int maximumSum(vector<int>& arr) {
        int n = arr.size();
        vector<long long> f(n), g(n);
        f[0] = g[n-1] = arr[0];
        for (int i = 1; i < n; i++) f[i] = max((long long)arr[i], f[i-1] + arr[i]);
        for (int i = n-2; i >= 0; i--) g[i] = max((long long)arr[i], g[i+1] + arr[i]);
        long long ans = *max_element(f.begin(), f.end());
        for (int i = 1; i < n-1; i++) ans = max(ans, f[i-1] + g[i+1]);
        return (int)ans;
    }
};

