class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        long[] f = new long[n], g = new long[n];
        f[0] = g[n-1] = arr[0];
        for (int i = 1; i < n; i++) f[i] = Math.max(arr[i], f[i-1] + arr[i]);
        for (int i = n-2; i >= 0; i--) g[i] = Math.max(arr[i], g[i+1] + arr[i]);
        long ans = Long.MIN_VALUE;
        for (long v : f) ans = Math.max(ans, v);
        for (int i = 1; i < n-1; i++) ans = Math.max(ans, f[i-1] + g[i+1]);
        return (int)ans;
    }
}

